(1789693, 245102, 3569, '<td valign="top">they look so much better in color</td>', 'they look so much better in color', '2005-10-17 09:06:44.000000', NULL, 1),
(1789694, 244446, 15711, '<td valign="top">WOW What a stunning reflection.  The sky and clouds are wonderful as a backdrop to the red, yellow and green. For some reason, the ground colors seem a tad over saturated. Maybe it''s just me.</td>', 'WOW What a stunning reflection.  The sky and clouds are wonderful as a backdrop to the red, yellow and green. For some reason, the ground colors seem a tad over saturated. Maybe it''s just me.', '2005-10-17 09:07:22.000000', NULL, 1),
(1789695, 244537, 15711, '<td valign="top">Oh I like this peek at the horse through the fence slats.  The leading line of the trees on the right is a nice touch as well. I wish his nose wasn''t covered but horses don''t "Sit and stay" like a dog. LOL  Good one.</td>', 'Oh I like this peek at the horse through the fence slats.  The leading line of the trees on the right is a nice touch as well. I wish his nose wasn''t covered but horses don''t "Sit and stay" like a dog. LOL  Good one.', '2005-10-17 09:09:04.000000', NULL, 1),
(1789696, 244279, 15711, '<td valign="top">I like the urban sense.  His legs show movement which adds interest. The curved metal sign against the flat stone building is a nice variation with a leading line aspect  as well. The light hitting the top of his head helps highlight him as the subject. I like it.</td>', 'I like the urban sense.  His legs show movement which adds interest. The curved metal sign against the flat stone building is a nice variation with a leading line aspect  as well. The light hitting the top of his head helps highlight him as the subject. I like it.', '2005-10-17 09:10:48.000000', NULL, 1),
(1789697, 245101, 15711, '<td valign="top">Love the building. It gives it some architecture and contrast with the white building and dark roof. Next time, use the maximum 640 pixels allowed, so that the image can be larger.</td>', 'Love the building. It gives it some architecture and contrast with the white building and dark roof. Next time, use the maximum 640 pixels allowed, so that the image can be larger.', '2005-10-17 09:11:29.000000', NULL, 1),
(1789698, 245020, 15711, '<td valign="top">Cool. I like the tree "growing" out of it. Beautiful blue tones. The grid makes for interesting eye candy.</td>', 'Cool. I like the tree "growing" out of it. Beautiful blue tones. The grid makes for interesting eye candy.', '2005-10-17 09:12:03.000000', NULL, 1),
(1789699, 244964, 15711, '<td valign="top">Very pretty.  Love the blue of the sky. The grasses at the bottom pushing up are a nice element of this shot. I like the sky showing through the taller trees too. 7</td>', 'Very pretty.  Love the blue of the sky. The grasses at the bottom pushing up are a nice element of this shot. I like the sky showing through the taller trees too. 7', '2005-10-17 09:13:03.000000', NULL, 1),
