(1789890, 244714, 42995, '<td valign="top">beautiful symmetry, detail.  a very nice wide angle shot!</td>', 'beautiful symmetry, detail.  a very nice wide angle shot!', '2005-10-17 11:25:57.000000', NULL, 1),
(1789893, 243157, 17446, '<td valign="top">You generally want to try and place your horizon either 1/3 of the way down the picture or 1/3 of the way up.  Having the horizon this centered causes my eye to bounce back and forth searching for an interesting foreground or sky.  Also, the shot may have improved with an object in the foreground (unless there is already something there in the dark that I can''t make out).  Nice colors captured here.</td>', 'You generally want to try and place your horizon either 1/3 of the way down the picture or 1/3 of the way up.  Having the horizon this centered causes my eye to bounce back and forth searching for an interesting foreground or sky.  Also, the shot may have improved with an object in the foreground (unless there is already something there in the dark that I can''t make out).  Nice colors captured here.', '2005-10-17 11:28:09.000000', NULL, 1),
(1789896, 243153, 42995, '<td valign="top">breathtaking!  i''ve seen many photos of amateur astronomers silhouetted against the night sky, but few that have done as nice a job as this.  beautiful colour, detail in the sky.  nice chioce to centre on pleiades.  i''d consider cloning out the satellite streaks for prints.  excellent work!!</td>', 'breathtaking!  i''ve seen many photos of amateur astronomers silhouetted against the night sky, but few that have done as nice a job as this.  beautiful colour, detail in the sky.  nice chioce to centre on pleiades.  i''d consider cloning out the satellite streaks for prints.  excellent work!!', '2005-10-17 11:30:03.000000', NULL, 1),
(1789897, 244708, 17446, '<td valign="top">This photo captures the atmosphere of the place.  Nice job placing the people in the frame.  The wide angle works well to be able to see the whole room floor to ceiling.</td>', 'This photo captures the atmosphere of the place.  Nice job placing the people in the frame.  The wide angle works well to be able to see the whole room floor to ceiling.', '2005-10-17 11:30:40.000000', NULL, 1),
(1789899, 243869, 42995, '<td valign="top">wonderful colour!  i really like this photo, might like it a tad sharper.  good work!</td>', 'wonderful colour!  i really like this photo, might like it a tad sharper.  good work!', '2005-10-17 11:30:50.000000', NULL, 1),
(1789900, 244909, 42995, '<td valign="top">beautiful, ethereal shot.  wonderful choice of wide trees, really nicely composed!</td>', 'beautiful, ethereal shot.  wonderful choice of wide trees, really nicely composed!', '2005-10-17 11:31:28.000000', NULL, 1),
(1789902, 244332, 42995, '<td valign="top">the rotting logs provide a nice counterpoint to the skyscrapers in the distance.  nicely done!</td>', 'the rotting logs provide a nice counterpoint to the skyscrapers in the distance.  nicely done!', '2005-10-17 11:32:05.000000', NULL, 1),
(1789906, 245015, 42995, '<td valign="top">wow, that''s quite the shot!  i really like it, but might like the colours a bit punchier to show off the city lights...great work!</td>', 'wow, that''s quite the shot!  i really like it, but might like the colours a bit punchier to show off the city lights...great work!', '2005-10-17 11:33:20.000000', NULL, 1),
(1789909, 244916, 42995, '<td valign="top">wonderful juxtaposition of the modern and traditional!  well done!</td>', 'wonderful juxtaposition of the modern and traditional!  well done!', '2005-10-17 11:35:29.000000', NULL, 1),
(1789913, 244489, 42995, '<td valign="top">very nice!  infrared look of sky gives it otherworldly-feel.  well done!</td>', 'very nice!  infrared look of sky gives it otherworldly-feel.  well done!', '2005-10-17 11:36:54.000000', NULL, 1),
(1789915, 244976, 42995, '<td valign="top">wonderful reflectdive shot.  the grid lines in the pool add to the sense of perspective.  nicely done!</td>', 'wonderful reflectdive shot.  the grid lines in the pool add to the sense of perspective.  nicely done!', '2005-10-17 11:37:35.000000', NULL, 1),
(1789917, 245141, 42995, '<td valign="top">i love this photo.  the textures and the brightness give this such a soft, light feel.  beautiful work!</td>', 'i love this photo.  the textures and the brightness give this such a soft, light feel.  beautiful work!', '2005-10-17 11:38:16.000000', NULL, 1),
