(1790514, 244917, 35545, '<td valign="top">I don''t think de-sat worked well here.  The whole thing looks too fake and/or over-processed.</td>', 'I don''t think de-sat worked well here.  The whole thing looks too fake and/or over-processed.', '2005-10-17 17:29:03.000000', NULL, 1),
(1790517, 243979, 45995, '<td valign="top">Wide angle sucked up into a hole, super, a really good photo with fantastic light.<br/>Great.</td>', 'Wide angle sucked up into a hole, super, a really good photo with fantastic light.Great.', '2005-10-17 17:30:37.000000', NULL, 1),
(1790518, 243807, 45995, '<td valign="top">Paradise, great shot with nice light</td>', 'Paradise, great shot with nice light', '2005-10-17 17:31:29.000000', NULL, 1),
(1790528, 244556, 35078, '<td valign="top">Very nicely framed.</td>', 'Very nicely framed.', '2005-10-17 17:39:43.000000', NULL, 1),
(1790534, 245179, 35078, '<td valign="top">Really nice idea, but looks a bit blurred on my monitor. Gaussin Blur?</td>', 'Really nice idea, but looks a bit blurred on my monitor. Gaussin Blur?', '2005-10-17 17:42:42.000000', NULL, 1),
(1790537, 245130, 35078, '<td valign="top">Great contrast in colours. Very similar to mine in respect to the clouds and coming storm.</td>', 'Great contrast in colours. Very similar to mine in respect to the clouds and coming storm.', '2005-10-17 17:44:01.000000', NULL, 1),
(1790544, 244174, 4967, '<td valign="top">Great use of the wide angle lens... thank you for making a pretty sun shot INTERESTING.  This is a very nice sillouhette, and a great capture.  One of my favorite shots so far... -10- Good luck!</td>', 'Great use of the wide angle lens... thank you for making a pretty sun shot INTERESTING.  This is a very nice sillouhette, and a great capture.  One of my favorite shots so far... -10- Good luck!', '2005-10-17 17:47:41.000000', NULL, 1),
(1790548, 244667, 4967, '<td valign="top">I would have loved to have seen a slightly different angle here... I like the fact that you got quite a bit of foreground in the picture... but what would this have looked like possibly laying down to attmept to make it look larger?  and with more foreground?  Just an idea. Good wide angle subject though...</td>', 'I would have loved to have seen a slightly different angle here... I like the fact that you got quite a bit of foreground in the picture... but what would this have looked like possibly laying down to attmept to make it look larger?  and with more foreground?  Just an idea. Good wide angle subject though...', '2005-10-17 17:49:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1790550, 243939, 35078, '<td valign="top">Cool effect. Would like to know how you did it at the end of the challenge.</td>', 'Cool effect. Would like to know how you did it at the end of the challenge.', '2005-10-17 17:51:54.000000', NULL, 1),
(1790551, 243157, 4967, '<td valign="top">I like the fact that you didn''t do the usual horizontal shot here... I think it lends itself well to your title... I would however have possibly liked to have seen more ocean (or maybe even sand (or whatever you were standing on)) and less sky - because the sky here isn''t partcularly spectacular.  Be careful... there is something to the "rule of thirds" your sun is almost dead center... which doesn''t allow for the eye to transverse the rest of the photo.</td>', 'I like the fact that you didn''t do the usual horizontal shot here... I think it lends itself well to your title... I would however have possibly liked to have seen more ocean (or maybe even sand (or whatever you were standing on)) and less sky - because the sky here isn''t partcularly spectacular.  Be careful... there is something to the "rule of thirds" your sun is almost dead center... which doesn''t allow for the eye to transverse the rest of the photo.', '2005-10-17 17:52:10.000000', NULL, 1),
(1790554, 242603, 4967, '<td valign="top">I like this... I think it is unique and different... and you made it a much more dynamic photo by not shooting a dead on photo with the fence straight in the background.  The sepia is an interesting choice and it makes it look like an old style photo if it weren''t for the camera and video camera in the photo!  I can see a lot of fun here... like a family outing to take photos and videos... My only wish was that I could see the whole dog within the frame... although I actually like the fact that the ladies'' feet aren''t in it.  Good luck with this... DPCers tend to not look kindly on unique shots... -8- from me :-).</td>', 'I like this... I think it is unique and different... and you made it a much more dynamic photo by not shooting a dead on photo with the fence straight in the background.  The sepia is an interesting choice and it makes it look like an old style photo if it weren''t for the camera and video camera in the photo!  I can see a lot of fun here... like a family outing to take photos and videos... My only wish was that I could see the whole dog within the frame... although I actually like the fact that the ladies'' feet aren''t in it.  Good luck with this... DPCers tend to not look kindly on unique shots... -8- from me :-).', '2005-10-17 17:55:37.000000', NULL, 1),
(1790556, 244364, 4967, '<td valign="top">For this one... it would have been REALLY neat to see a shot taken from your belly looking almost straight up at the wheat(?).  Did you try this in a black and white?  Just curious.</td>', 'For this one... it would have been REALLY neat to see a shot taken from your belly looking almost straight up at the wheat(?).  Did you try this in a black and white?  Just curious.', '2005-10-17 17:57:17.000000', NULL, 1),
(1790560, 244976, 4967, '<td valign="top">This is a pretty neat, a great reflection that''s for sure (did you go looking for a reflection shot?) The roundness here lends itself well to the wide angle shot... -9-</td>', 'This is a pretty neat, a great reflection that''s for sure (did you go looking for a reflection shot?) The roundness here lends itself well to the wide angle shot... -9-', '2005-10-17 17:59:30.000000', NULL, 1),
(1790572, 244124, 27164, '<td valign="top">Nice photo with beautiful colors, I just wish the horizon weren''t so centered - this image would be great improved IMHO if the bottom strip of mostly-black were cropped off.</td>', 'Nice photo with beautiful colors, I just wish the horizon weren''t so centered - this image would be great improved IMHO if the bottom strip of mostly-black were cropped off.', '2005-10-17 18:12:30.000000', NULL, 1),
(1790573, 245015, 27164, '<td valign="top">Wonderful use of fisheye distortion, top ten for sure.  I like this one a lot.</td>', 'Wonderful use of fisheye distortion, top ten for sure.  I like this one a lot.', '2005-10-17 18:13:16.000000', NULL, 1),
(1790578, 244907, 44754, '<td valign="top">Funny :)</td>', 'Funny :)', '2005-10-17 18:19:03.000000', NULL, 1),
(1790581, 244991, 45115, '<td valign="top">WTF does it have to do with wide angle?</td>', 'WTF does it have to do with wide angle?', '2005-10-17 18:22:50.000000', NULL, 1),
