(1792429, 244338, 17446, '<td valign="top">Nice job.  I love the black and white.  I love the man walking out of the blown out white light.  This isn''t half as interesting without the person.  The wide angle provides a good sense of the vast emptiness in the room.  9.</td>', 'Nice job.  I love the black and white.  I love the man walking out of the blown out white light.  This isn''t half as interesting without the person.  The wide angle provides a good sense of the vast emptiness in the room.  9.', '2005-10-18 11:45:06.000000', NULL, 1),
(1792431, 245021, 17446, '<td valign="top">Great colors.  Great sky.  Great desert feel.  The wide angle adds to the sense of the vastness of the desert.  Nice job.  top ten in my book.</td>', 'Great colors.  Great sky.  Great desert feel.  The wide angle adds to the sense of the vastness of the desert.  Nice job.  top ten in my book.', '2005-10-18 11:45:31.000000', NULL, 1),
(1792432, 244083, 17446, '<td valign="top">I think the black and white was an excellent idea for this shot.  Nice job.  top ten in my book.</td>', 'I think the black and white was an excellent idea for this shot.  Nice job.  top ten in my book.', '2005-10-18 11:45:42.000000', NULL, 1),
(1792434, 245129, 17446, '<td valign="top">Great colors (and complementary)!  Blues in the sky leading to oranges in the trees.  Good job.  top ten for me.</td>', 'Great colors (and complementary)!  Blues in the sky leading to oranges in the trees.  Good job.  top ten for me.', '2005-10-18 11:45:55.000000', NULL, 1),
(1792436, 243473, 17446, '<td valign="top">I like this one very well.  The wide angle lens pointed straight up captures the height of the buildings.   Top ten for me.</td>', 'I like this one very well.  The wide angle lens pointed straight up captures the height of the buildings.   Top ten for me.', '2005-10-18 11:46:18.000000', NULL, 1),
(1792441, 245150, 17446, '<td valign="top">This gets a top ten vote from me.  I love the extent of the photo from mountains in the distance all the way to the ground below.</td>', 'This gets a top ten vote from me.  I love the extent of the photo from mountains in the distance all the way to the ground below.', '2005-10-18 11:47:07.000000', NULL, 1),
(1792442, 244465, 17446, '<td valign="top">Nice placement of the horizon.  I love all the blue tones and the simplistic, uncluttered feel.  Top ten from me.</td>', 'Nice placement of the horizon.  I love all the blue tones and the simplistic, uncluttered feel.  Top ten from me.', '2005-10-18 11:47:46.000000', NULL, 1),
