(1794036, 245146, 41675, '<td valign="top">Interesting entry. For me, while I think it''s a good shot of a computer, the subject matter doesn''t hold my visual interest as well as other entries in this challenge.</td>', 'Interesting entry. For me, while I think it''s a good shot of a computer, the subject matter doesn''t hold my visual interest as well as other entries in this challenge.', '2005-10-18 23:58:27.000000', NULL, 1),
(1794039, 244525, 41675, '<td valign="top">My favorite part is the very small area of the lit field itself. Everything else in your photo is so black, I wish there was more of that field visible. Also, the light flare is a little distracting for me.</td>', 'My favorite part is the very small area of the lit field itself. Everything else in your photo is so black, I wish there was more of that field visible. Also, the light flare is a little distracting for me.', '2005-10-18 23:59:33.000000', NULL, 1),
