(1799102, 244015, 23053, '<td valign="top">Cool symetry here...nice light and colors.</td>', 'Cool symetry here...nice light and colors.', '2005-10-20 18:20:10.000000', NULL, 1),
(1799108, 244279, 30392, '<td valign="top">I love this one, great composition and DOF, the man in the suit makes it perfect. It tells a story, not sure which one but it does!</td>', 'I love this one, great composition and DOF, the man in the suit makes it perfect. It tells a story, not sure which one but it does!', '2005-10-20 18:21:58.000000', NULL, 1),
(1799112, 245094, 23053, '<td valign="top">I can''t put my finger on it, but there is something odd about the clouds here...they almost look unreal, or maybe like a negative of what was actually there.  I dunno...definately creepy, no matter what.</td>', 'I can''t put my finger on it, but there is something odd about the clouds here...they almost look unreal, or maybe like a negative of what was actually there.  I dunno...definately creepy, no matter what.', '2005-10-20 18:23:51.000000', NULL, 1),
(1799122, 245141, 6532, '<td valign="top">I see something like this almost every morning on my way to work.  I frequently wondered about how to best capture the scene.  Good job here!  The only thing that is bothersome is the dark foreground corner.</td>', 'I see something like this almost every morning on my way to work.  I frequently wondered about how to best capture the scene.  Good job here!  The only thing that is bothersome is the dark foreground corner.', '2005-10-20 18:26:48.000000', NULL, 1),
(1799124, 244714, 6532, '<td valign="top">Cool!  I like the distortion and the balance.</td>', 'Cool!  I like the distortion and the balance.', '2005-10-20 18:27:21.000000', NULL, 1),
(1799125, 244050, 6532, '<td valign="top">My eye is drawn to the bright spot in the sky.  A bit too much.  Good idea.  Just turn down the brightness.</td>', 'My eye is drawn to the bright spot in the sky.  A bit too much.  Good idea.  Just turn down the brightness.', '2005-10-20 18:28:26.000000', NULL, 1),
(1799130, 245095, 6532, '<td valign="top">Nice pic.  What is in the upper background?  It is a bit distracting.  I like how the house acts as an anchor.</td>', 'Nice pic.  What is in the upper background?  It is a bit distracting.  I like how the house acts as an anchor.', '2005-10-20 18:29:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1799136, 243991, 6532, '<td valign="top">Wow! Cool picture. I like all the tones.  B&amp;W works nicely on this one.</td>', 'Wow! Cool picture. I like all the tones.  B&W works nicely on this one.', '2005-10-20 18:32:06.000000', NULL, 1),
(1799143, 245096, 6532, '<td valign="top">Interesting - this is like an optical illusion when you use the side bar to raise/lower the image on the screen.</td>', 'Interesting - this is like an optical illusion when you use the side bar to raise/lower the image on the screen.', '2005-10-20 18:34:00.000000', NULL, 1),
(1799144, 243157, 6532, '<td valign="top">Appears to be a bit over saturated!</td>', 'Appears to be a bit over saturated!', '2005-10-20 18:34:39.000000', NULL, 1),
(1799151, 245169, 6532, '<td valign="top">Appears to be a bit over saturated.  The hint of green on the left border is also bothersome.</td>', 'Appears to be a bit over saturated.  The hint of green on the left border is also bothersome.', '2005-10-20 18:37:46.000000', NULL, 1),
(1799153, 244721, 6532, '<td valign="top">I think it may have been more effective to cut off the grass foreground.</td>', 'I think it may have been more effective to cut off the grass foreground.', '2005-10-20 18:39:00.000000', NULL, 1),
(1799159, 245099, 6532, '<td valign="top">The bit of horizontal foreground is probably unnecessary.  I know it is difficult to balance the light in this type of subject but I think you could have gone a bit lighter.  Maybe shot the photo at dawn or dusk.</td>', 'The bit of horizontal foreground is probably unnecessary.  I know it is difficult to balance the light in this type of subject but I think you could have gone a bit lighter.  Maybe shot the photo at dawn or dusk.', '2005-10-20 18:41:09.000000', NULL, 1),
(1799163, 244228, 6532, '<td valign="top">The photo is great as far as the subject and colors.  The border?  Well, even though I usually favor borders - in this case I do not like it!  Still a 7</td>', 'The photo is great as far as the subject and colors.  The border?  Well, even though I usually favor borders - in this case I do not like it!  Still a 7', '2005-10-20 18:42:52.000000', NULL, 1),
(1799167, 244124, 6532, '<td valign="top">The sky appears to be oversaturated.</td>', 'The sky appears to be oversaturated.', '2005-10-20 18:45:02.000000', NULL, 1),
(1799168, 243934, 6532, '<td valign="top">Wow.  Nice capture.  The lines work as well.  Good job.</td>', 'Wow.  Nice capture.  The lines work as well.  Good job.', '2005-10-20 18:45:46.000000', NULL, 1),
(1799169, 243560, 6532, '<td valign="top">Nice.  Creative approach on a simple subject.</td>', 'Nice.  Creative approach on a simple subject.', '2005-10-20 18:46:22.000000', NULL, 1),
(1799170, 244691, 6532, '<td valign="top">The light seems weird, a bit too yellow?  The hint of column in the upper right is distracting.</td>', 'The light seems weird, a bit too yellow?  The hint of column in the upper right is distracting.', '2005-10-20 18:47:36.000000', NULL, 1),
(1799176, 244968, 6532, '<td valign="top">Interesting use of the gray tones(?).</td>', 'Interesting use of the gray tones(?).', '2005-10-20 18:54:08.000000', NULL, 1),
(1799183, 245139, 34013, '<td valign="top">gorgeous!</td>', 'gorgeous!', '2005-10-20 19:08:00.000000', NULL, 1),
(1799187, 244919, 34013, '<td valign="top">looks like a painting.....gorgeous!</td>', 'looks like a painting.....gorgeous!', '2005-10-20 19:09:01.000000', NULL, 1),
