(1799204, 245141, 34013, '<td valign="top">wow! gorgeous!!!</td>', 'wow! gorgeous!!!', '2005-10-20 19:16:21.000000', NULL, 1),
(1799210, 244976, 4767, '<td valign="top">Looking southward instead of towrd the temple here.  Nice change! Good use of the wider aspect as well.</td>', 'Looking southward instead of towrd the temple here.  Nice change! Good use of the wider aspect as well.', '2005-10-20 19:18:42.000000', NULL, 1),
(1799214, 244976, 6532, '<td valign="top">Seems like this is leaning to the left.  Otherwise, it is a good idea with nice clarity.</td>', 'Seems like this is leaning to the left.  Otherwise, it is a good idea with nice clarity.', '2005-10-20 19:19:17.000000', NULL, 1),
(1799215, 244680, 34013, '<td valign="top">mmm! reminds me of the corona commercials......so inviting......!</td>', 'mmm! reminds me of the corona commercials......so inviting......!', '2005-10-20 19:19:23.000000', NULL, 1),
(1799221, 242588, 6532, '<td valign="top">Appears to be oversaturated and blurry.</td>', 'Appears to be oversaturated and blurry.', '2005-10-20 19:21:19.000000', NULL, 1),
(1799223, 245037, 4767, '<td valign="top">Must be military pumpkins - such straight rows!  Around here, they grow in any pattern they like.  Good use of complementary colors, and eye-catching photo!</td>', 'Must be military pumpkins - such straight rows!  Around here, they grow in any pattern they like.  Good use of complementary colors, and eye-catching photo!', '2005-10-20 19:21:23.000000', NULL, 1),
(1799224, 244913, 4767, '<td valign="top">Far out, Man.  It''s like, you know, a flashback to the good old days. Peace.</td>', 'Far out, Man.  It''s like, you know, a flashback to the good old days. Peace.', '2005-10-20 19:22:49.000000', NULL, 1),
(1799226, 244978, 6532, '<td valign="top">Nice.  I like the scale as well as the simplicity.</td>', 'Nice.  I like the scale as well as the simplicity.', '2005-10-20 19:24:02.000000', NULL, 1),
(1799235, 244866, 6532, '<td valign="top">I do not understand what the goal is.  I think this would have been more interesting with the color on the trees entirely.</td>', 'I do not understand what the goal is.  I think this would have been more interesting with the color on the trees entirely.', '2005-10-20 19:27:30.000000', NULL, 1),
