(1799362, 244042, 40718, '<td valign="top">I was too chicken to enter my "mini" wide angle.  Who says it needs to be a panorama?  Creative and well done.  8</td>', 'I was too chicken to enter my "mini" wide angle.  Who says it needs to be a panorama?  Creative and well done.  8', '2005-10-20 20:24:21.000000', NULL, 1),
