(1799606, 244352, 17507, '<td valign="top">I think a bit of burning on the ground might have helped accentuate the path and thus the sense of depth.</td>', 'I think a bit of burning on the ground might have helped accentuate the path and thus the sense of depth.', '2005-10-20 22:03:35.000000', NULL, 1),
(1799608, 244978, 17507, '<td valign="top">excellent desaturation and image in general</td>', 'excellent desaturation and image in general', '2005-10-20 22:04:15.000000', NULL, 1),
(1799610, 244174, 17507, '<td valign="top">I think that moving farther to your left might have helped accentuate the perspective in this photo</td>', 'I think that moving farther to your left might have helped accentuate the perspective in this photo', '2005-10-20 22:04:47.000000', NULL, 1),
(1799616, 244613, 17507, '<td valign="top">If this was shot with a wide-angle lens, I cannot tell at all...</td>', 'If this was shot with a wide-angle lens, I cannot tell at all...', '2005-10-20 22:06:36.000000', NULL, 1),
