(1799638, 245147, 17507, '<td valign="top">Great perspective! too bad that building with the vertical stripes turned into a mess of jaggies...</td>', 'Great perspective! too bad that building with the vertical stripes turned into a mess of jaggies...', '2005-10-20 22:11:15.000000', NULL, 1),
(1799643, 244991, 17507, '<td valign="top">oo cellophane... hot!</td>', 'oo cellophane... hot!', '2005-10-20 22:11:58.000000', NULL, 1),
