(1805186, 245021, 27845, '<td valign="top">I think this would do much better in B&amp;W. 6.</td>', 'I think this would do much better in B&W. 6.', '2005-10-23 16:44:47.000000', NULL, 1),
(1805187, 243465, 27845, '<td valign="top">Hm, a bit hard to see. Maybe if you had moved closer to the boxes the open one would have popped out better. 4.</td>', 'Hm, a bit hard to see. Maybe if you had moved closer to the boxes the open one would have popped out better. 4.', '2005-10-23 16:46:01.000000', NULL, 1),
(1805188, 245092, 43115, '<td valign="top">This is a powerful image.  This scene does a great job of emoting emptyness.  I wish it was a little sharper, and I wish it wasn''t so over exposed in the right side because that almost makes me feel "hope" or something similar.  Good Job.</td>', 'This is a powerful image.  This scene does a great job of emoting emptyness.  I wish it was a little sharper, and I wish it wasn''t so over exposed in the right side because that almost makes me feel "hope" or something similar.  Good Job.', '2005-10-23 16:46:13.000000', NULL, 1),
(1805190, 244731, 36606, '<td valign="top">i think you could have taken a more effective photo if you simplified things. Seems messy to me. Too many branches and clutter. Also maybe you could have taken the photo at a better hour, like sunset, and had a more dramtic sky. Good luck anyway!!</td>', 'i think you could have taken a more effective photo if you simplified things. Seems messy to me. Too many branches and clutter. Also maybe you could have taken the photo at a better hour, like sunset, and had a more dramtic sky. Good luck anyway!!', '2005-10-23 16:46:50.000000', NULL, 1),
(1805191, 244714, 27845, '<td valign="top">Very good idea! Kudos for having the courage tor stick the lens into unusual places. 10.</td>', 'Very good idea! Kudos for having the courage tor stick the lens into unusual places. 10.', '2005-10-23 16:47:01.000000', NULL, 1),
(1805194, 243304, 27845, '<td valign="top">Interesting hue. I see I''m not the only one who got up for dawn for this challenge :) 9.</td>', 'Interesting hue. I see I''m not the only one who got up for dawn for this challenge :) 9.', '2005-10-23 16:48:33.000000', NULL, 1),
(1805195, 245141, 36606, '<td valign="top">Wow, i absolutely love this. Great conditions. Almost dreamlike. Co,ouring is fabulous. Good luck! (9)</td>', 'Wow, i absolutely love this. Great conditions. Almost dreamlike. Co,ouring is fabulous. Good luck! (9)', '2005-10-23 16:48:47.000000', NULL, 1),
(1805197, 245105, 43115, '<td valign="top">Goregous scene.  I love the sharpness.  This shot <i>should</i> be dull with the grey sky, grey water, and general grey, but it''s not!  I think the plane, the grass, and the peeks of blue add just enough vibrance to this shot.  Color saturation and contrast are great.  Great job!</td>', 'Goregous scene.  I love the sharpness.  This shot should be dull with the grey sky, grey water, and general grey, but it''s not!  I think the plane, the grass, and the peeks of blue add just enough vibrance to this shot.  Color saturation and contrast are great.  Great job!', '2005-10-23 16:51:00.000000', NULL, 1),
(1805198, 244286, 36606, '<td valign="top">For me personally, I think you have chosen the beach where some fantastic photos have been taken, and you havent captured it as good. Reason - I think sunset or sunrise would have resulted in a far better photo. Good luck though.</td>', 'For me personally, I think you have chosen the beach where some fantastic photos have been taken, and you havent captured it as good. Reason - I think sunset or sunrise would have resulted in a far better photo. Good luck though.', '2005-10-23 16:51:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1805200, 245015, 43115, '<td valign="top">Even it it''s accidental... the "Need more space" billboard plays off the challenge theme so wonderfuly!  I love the ominous sky too.</td>', 'Even it it''s accidental... the "Need more space" billboard plays off the challenge theme so wonderfuly!  I love the ominous sky too.', '2005-10-23 16:52:46.000000', NULL, 1),
(1805205, 243153, 36606, '<td valign="top">Amazing photo!! This makes me feel alive. Part of the universe! Best of luck! Hoping you get a ribbon for this! (10) and a new favourite!</td>', 'Amazing photo!! This makes me feel alive. Part of the universe! Best of luck! Hoping you get a ribbon for this! (10) and a new favourite!', '2005-10-23 16:55:01.000000', NULL, 1),
(1805207, 245015, 27845, '<td valign="top">Excellent use of the Fisheye. I like the gloom around the buildings. D&amp;B? 10. Adding to favs.</td>', 'Excellent use of the Fisheye. I like the gloom around the buildings. D&B? 10. Adding to favs.', '2005-10-23 16:55:14.000000', NULL, 1),
(1805209, 243807, 43115, '<td valign="top">I love the sun shining on the trees just in the corner of the photo.  Great capture.</td>', 'I love the sun shining on the trees just in the corner of the photo.  Great capture.', '2005-10-23 16:55:48.000000', NULL, 1),
(1805210, 244452, 27845, '<td valign="top">I like the clarity and the sobre strictness. Good lightness tones. 8.</td>', 'I like the clarity and the sobre strictness. Good lightness tones. 8.', '2005-10-23 16:55:57.000000', NULL, 1),
(1805211, 245015, 36606, '<td valign="top">Wow! top notch photo! WOnderful colouring, drama in the sky and perspective! (9)</td>', 'Wow! top notch photo! WOnderful colouring, drama in the sky and perspective! (9)', '2005-10-23 16:56:18.000000', NULL, 1),
(1805254, 243991, 43115, '<td valign="top">This photo tells a story so well.  It has such strong emotion.  Good job!</td>', 'This photo tells a story so well.  It has such strong emotion.  Good job!', '2005-10-23 17:26:21.000000', NULL, 1),
(1805256, 243997, 43115, '<td valign="top">Such strong emotion in this photo!</td>', 'Such strong emotion in this photo!', '2005-10-23 17:28:21.000000', NULL, 1),
(1805273, 244981, 43115, '<td valign="top">I don''t care for the conversion to B&amp;W for this shot.  I bet there was some spectacular color here...</td>', 'I don''t care for the conversion to B&W for this shot.  I bet there was some spectacular color here...', '2005-10-23 17:40:07.000000', NULL, 1),
(1805274, 243153, 43115, '<td valign="top">I love the guy with the tripod, far off in the distance... :)</td>', 'I love the guy with the tripod, far off in the distance... :)', '2005-10-23 17:40:34.000000', NULL, 1),
(1805277, 244998, 43115, '<td valign="top">I really like this shot.  I love the color and saturation, I love the sharpness, I love the perspective.  Really good photo.</td>', 'I really like this shot.  I love the color and saturation, I love the sharpness, I love the perspective.  Really good photo.', '2005-10-23 17:43:48.000000', NULL, 1),
(1805278, 244913, 43115, '<td valign="top">The only thing I dislike about this shot is that the ominous sky seems to be in total conflict with "peace and love."  I wish there was a happy, blue sky in the background.</td>', 'The only thing I dislike about this shot is that the ominous sky seems to be in total conflict with "peace and love."  I wish there was a happy, blue sky in the background.', '2005-10-23 17:45:16.000000', NULL, 1),
(1805279, 244538, 43115, '<td valign="top">Not enough detail in the foreground.</td>', 'Not enough detail in the foreground.', '2005-10-23 17:48:43.000000', NULL, 1),
(1805280, 244889, 43115, '<td valign="top">This shot feels flat... the brown tones are too similar and there''s not enough contrast between the brown and the green.</td>', 'This shot feels flat... the brown tones are too similar and there''s not enough contrast between the brown and the green.', '2005-10-23 17:49:42.000000', NULL, 1),
(1805284, 244551, 43115, '<td valign="top">The motion blur of the folks in the foreground is unfortunate and detracts from what could otherwise be a very highly rated photo.</td>', 'The motion blur of the folks in the foreground is unfortunate and detracts from what could otherwise be a very highly rated photo.', '2005-10-23 17:52:22.000000', NULL, 1),
(1805291, 244552, 43115, '<td valign="top">I love the sun streaming through the clouds, but the foreground is just too... strange... for me to rank this as a 10.</td>', 'I love the sun streaming through the clouds, but the foreground is just too... strange... for me to rank this as a 10.', '2005-10-23 17:58:44.000000', NULL, 1),
(1805293, 242603, 43115, '<td valign="top">Cute, but I don''t care for the tilt or the grain.</td>', 'Cute, but I don''t care for the tilt or the grain.', '2005-10-23 17:59:11.000000', NULL, 1),
(1805294, 244497, 43115, '<td valign="top">I love the sharpness in the foreground of this photo.</td>', 'I love the sharpness in the foreground of this photo.', '2005-10-23 17:59:38.000000', NULL, 1),
(1805302, 244714, 43115, '<td valign="top">I like the perspective of this shot.</td>', 'I like the perspective of this shot.', '2005-10-23 18:05:39.000000', NULL, 1),
(1805305, 245172, 18374, '<td valign="top">Very nice capture.  The color on the trees adds a lot to this photo for me.</td>', 'Very nice capture.  The color on the trees adds a lot to this photo for me.', '2005-10-23 18:09:47.000000', NULL, 1),
(1805310, 244852, 18374, '<td valign="top">I like this shot.  Nice, soft blur on the water and good color in the sky.</td>', 'I like this shot.  Nice, soft blur on the water and good color in the sky.', '2005-10-23 18:11:52.000000', NULL, 1),
(1805318, 245014, 18374, '<td valign="top">I like this photo.  This is a great use of a wide angle.  Very effective.  Nice job with the solid focus throughout the field of view.</td>', 'I like this photo.  This is a great use of a wide angle.  Very effective.  Nice job with the solid focus throughout the field of view.', '2005-10-23 18:13:59.000000', NULL, 1),
(1805319, 244913, 18374, '<td valign="top">Simple, yet striking.  Nice job and effective use of the wide angle.</td>', 'Simple, yet striking.  Nice job and effective use of the wide angle.', '2005-10-23 18:15:02.000000', NULL, 1),
(1805321, 245174, 18374, '<td valign="top">I love the color and reflections in this shot.  Nicely done!</td>', 'I love the color and reflections in this shot.  Nicely done!', '2005-10-23 18:15:39.000000', NULL, 1),
(1805326, 244541, 18374, '<td valign="top">Very nice.  I like the starbursts on the lights.</td>', 'Very nice.  I like the starbursts on the lights.', '2005-10-23 18:16:28.000000', NULL, 1),
(1805327, 245163, 43115, '<td valign="top">Generally flat and lacking contrast... too much green!</td>', 'Generally flat and lacking contrast... too much green!', '2005-10-23 18:16:29.000000', NULL, 1),
(1805333, 245133, 43115, '<td valign="top">I think a polarizing filter would have cut the haze and made this sky <b>really</b> blue.</td>', 'I think a polarizing filter would have cut the haze and made this sky really blue.', '2005-10-23 18:18:21.000000', NULL, 1),
(1805336, 244188, 43115, '<td valign="top">Neat idea, but a bit of a boring shot.</td>', 'Neat idea, but a bit of a boring shot.', '2005-10-23 18:19:35.000000', NULL, 1),
(1805340, 244525, 18374, '<td valign="top">While this may be wide angle, most of the image is lost in the blackness.  The small strip of green on the field seems very distant.  The lights in the upper right are a bit distracting as well.  Using a flash and adding some element of interest to the foreground might add interest to this image.  Also, moving to another location to take the shot, such as near a sideline where you can fill the frame with the field might also help.</td>', 'While this may be wide angle, most of the image is lost in the blackness.  The small strip of green on the field seems very distant.  The lights in the upper right are a bit distracting as well.  Using a flash and adding some element of interest to the foreground might add interest to this image.  Also, moving to another location to take the shot, such as near a sideline where you can fill the frame with the field might also help.', '2005-10-23 18:20:09.000000', NULL, 1),
(1805342, 242588, 18374, '<td valign="top">I would have scored this higher if it had been in focus.</td>', 'I would have scored this higher if it had been in focus.', '2005-10-23 18:21:21.000000', NULL, 1),
(1805346, 245085, 43115, '<td valign="top">I don''t care for the tilt on this photo, though I really like the slight motion blur on the girl.</td>', 'I don''t care for the tilt on this photo, though I really like the slight motion blur on the girl.', '2005-10-23 18:22:50.000000', NULL, 1),
(1805351, 244995, 43115, '<td valign="top">A bit too much USM, I think.</td>', 'A bit too much USM, I think.', '2005-10-23 18:24:22.000000', NULL, 1),
(1805352, 245146, 18374, '<td valign="top">Technically, this image is fine- good focus and exposure.  Artistically, it doesn''t appeal to me.  The brown carpet doesn''t make a very good backdrop.  A head on, centered shot is kind of dull here, and the subject matter is not all that interesting.  Try getting creative with the angle you are shooting at or the lighting to add some punch to the picture.</td>', 'Technically, this image is fine- good focus and exposure.  Artistically, it doesn''t appeal to me.  The brown carpet doesn''t make a very good backdrop.  A head on, centered shot is kind of dull here, and the subject matter is not all that interesting.  Try getting creative with the angle you are shooting at or the lighting to add some punch to the picture.', '2005-10-23 18:25:06.000000', NULL, 1),
(1805355, 245010, 43115, '<td valign="top">A bit too much of the rocks in the foreground, I think.</td>', 'A bit too much of the rocks in the foreground, I think.', '2005-10-23 18:25:50.000000', NULL, 1),
(1805356, 245169, 43115, '<td valign="top">Good perspective, but I would have cropped out the little green bit on the left.</td>', 'Good perspective, but I would have cropped out the little green bit on the left.', '2005-10-23 18:26:11.000000', NULL, 1),
(1805359, 242545, 43115, '<td valign="top">It''s a pretty scene, but I think there''s a bit too much glow for my personal taste.</td>', 'It''s a pretty scene, but I think there''s a bit too much glow for my personal taste.', '2005-10-23 18:29:26.000000', NULL, 1),
(1805380, 243475, 3554, '<td valign="top">While this photo meets the challenge, just fine, the shot itself seems cuttered and busy. My eye wanders from the boat to the bridge to the reflection, never sure where to settle.</td>', 'While this photo meets the challenge, just fine, the shot itself seems cuttered and busy. My eye wanders from the boat to the bridge to the reflection, never sure where to settle.', '2005-10-23 18:49:18.000000', NULL, 1),
(1805384, 245146, 3554, '<td valign="top">The lighting in this shot isn''t doing much to enhance it. It seems very flat and even which makes the picture sort of dull. Try lighting from the side to give shadows and three dimensions. Also, nothing really seems in focus. Try focusing on he "Intel Inside" sticker.  Finally try this shot in black and white...I don''t think the color adds anything to this one.</td>', 'The lighting in this shot isn''t doing much to enhance it. It seems very flat and even which makes the picture sort of dull. Try lighting from the side to give shadows and three dimensions. Also, nothing really seems in focus. Try focusing on he "Intel Inside" sticker.  Finally try this shot in black and white...I don''t think the color adds anything to this one.', '2005-10-23 18:52:57.000000', NULL, 1),
(1805388, 244925, 3554, '<td valign="top">Several things to try to improve this image. Shoot when the horse is looking toward you. Don''t center the horse in the middle of the frame. Shoot earlier or later in the day when you get some shadows to add the third dimension to your picture.</td>', 'Several things to try to improve this image. Shoot when the horse is looking toward you. Don''t center the horse in the middle of the frame. Shoot earlier or later in the day when you get some shadows to add the third dimension to your picture.', '2005-10-23 18:55:08.000000', NULL, 1),
(1805389, 244446, 3554, '<td valign="top">I''m not a big fan of the highly sharpened look. The clouds look cool, but all the foliage looks wrong.</td>', 'I''m not a big fan of the highly sharpened look. The clouds look cool, but all the foliage looks wrong.', '2005-10-23 18:56:07.000000', NULL, 1),
(1805392, 243972, 3554, '<td valign="top">Good concept. The color/lighting seems flat and uninteresting. Maybe try this in black and white? Also I would have cropped it so you don''t see the ground in the bottom left. I think that ruins the overall effect.</td>', 'Good concept. The color/lighting seems flat and uninteresting. Maybe try this in black and white? Also I would have cropped it so you don''t see the ground in the bottom left. I think that ruins the overall effect.', '2005-10-23 18:57:28.000000', NULL, 1),
(1805393, 244714, 8860, '<td valign="top">Very strong, rich shot - like the dynamism in the shapes here.</td>', 'Very strong, rich shot - like the dynamism in the shapes here.', '2005-10-23 18:58:41.000000', NULL, 1),
(1805395, 244909, 3554, '<td valign="top">Pretty nice shot. I''m sure others have mentioned it, but I would have shifted left to get the whole tree in the frame. This is a great example of a time when breaking the rule of thirds would enhance the shot. I would have centered the big tree I think.</td>', 'Pretty nice shot. I''m sure others have mentioned it, but I would have shifted left to get the whole tree in the frame. This is a great example of a time when breaking the rule of thirds would enhance the shot. I would have centered the big tree I think.', '2005-10-23 18:59:48.000000', NULL, 1),
(1805397, 244465, 8860, '<td valign="top">Great subject and amazing light. Simple and effective use of space.</td>', 'Great subject and amazing light. Simple and effective use of space.', '2005-10-23 19:01:12.000000', NULL, 1),
(1805398, 242884, 3554, '<td valign="top">If you cropped the shot so you didnt see the brush along the top edge it would give a much more repetitious feel to it. I think the stuf along the top edge severely detracts from this photo.</td>', 'If you cropped the shot so you didnt see the brush along the top edge it would give a much more repetitious feel to it. I think the stuf along the top edge severely detracts from this photo.', '2005-10-23 19:01:22.000000', NULL, 1),
(1805483, 244193, 7910, '<td valign="top">interesting angle.</td>', 'interesting angle.', '2005-10-23 19:50:19.000000', NULL, 1),
(1805484, 243523, 7910, '<td valign="top">very nice</td>', 'very nice', '2005-10-23 19:50:36.000000', NULL, 1),
(1805485, 244907, 7910, '<td valign="top">creative.</td>', 'creative.', '2005-10-23 19:51:03.000000', NULL, 1),
(1805487, 245095, 7910, '<td valign="top">One of those times when centered composition really works.   Well done. - 10</td>', 'One of those times when centered composition really works.   Well done. - 10', '2005-10-23 19:52:20.000000', NULL, 1),
(1805489, 244532, 7910, '<td valign="top">Nice location, but a little too long on the exposure.</td>', 'Nice location, but a little too long on the exposure.', '2005-10-23 19:53:23.000000', NULL, 1),
(1805491, 244446, 7910, '<td valign="top">looks a little heavy on the sharpening.</td>', 'looks a little heavy on the sharpening.', '2005-10-23 19:54:16.000000', NULL, 1),
(1805498, 245039, 7910, '<td valign="top">Cool shot.</td>', 'Cool shot.', '2005-10-23 19:55:26.000000', NULL, 1),
(1805508, 244917, 7910, '<td valign="top">amazing capture</td>', 'amazing capture', '2005-10-23 19:58:03.000000', NULL, 1),
(1805510, 244724, 7910, '<td valign="top">sunset ray?  More like lens flare.   Nice scene though.</td>', 'sunset ray?  More like lens flare.   Nice scene though.', '2005-10-23 20:00:01.000000', NULL, 1),
(1805515, 244708, 43115, '<td valign="top">Too much noise/artifacting, especially on the people. :(  Interesting scene.</td>', 'Too much noise/artifacting, especially on the people. :(  Interesting scene.', '2005-10-23 20:02:58.000000', NULL, 1),
(1805517, 244786, 43115, '<td valign="top">Too much USM?  The edges of the cactus in the foreground look like they are glowing.</td>', 'Too much USM?  The edges of the cactus in the foreground look like they are glowing.', '2005-10-23 20:04:15.000000', NULL, 1),
(1805518, 244910, 43115, '<td valign="top">I appreciate the misty look and feel you were going for... however, I think something, particularly one of the rock faces should have been in better focus.</td>', 'I appreciate the misty look and feel you were going for... however, I think something, particularly one of the rock faces should have been in better focus.', '2005-10-23 20:05:11.000000', NULL, 1),
(1805519, 245061, 43115, '<td valign="top">Nice and sharp.  The lens distortion adds to the unique perspective.</td>', 'Nice and sharp.  The lens distortion adds to the unique perspective.', '2005-10-23 20:05:38.000000', NULL, 1),
(1805520, 242946, 43115, '<td valign="top">Very vibrant colors and nice and sharp.  Good job!</td>', 'Very vibrant colors and nice and sharp.  Good job!', '2005-10-23 20:06:15.000000', NULL, 1),
(1805521, 245101, 43115, '<td valign="top">I wish this wasn''t black and white, especially if there were some bright yellows and reds in here.  I think it could have had even more visual impact if it were in color.</td>', 'I wish this wasn''t black and white, especially if there were some bright yellows and reds in here.  I think it could have had even more visual impact if it were in color.', '2005-10-23 20:07:19.000000', NULL, 1),
(1805522, 244735, 43115, '<td valign="top">Pristine reflection... it''s so clear... Outstanding!  Wonder how it would look composed without the grass in the foreground?  Good capture.</td>', 'Pristine reflection... it''s so clear... Outstanding!  Wonder how it would look composed without the grass in the foreground?  Good capture.', '2005-10-23 20:08:15.000000', NULL, 1),
(1805525, 244465, 43115, '<td valign="top">I would be scared to be standing there, if that really is cracking ice... Very good capture.</td>', 'I would be scared to be standing there, if that really is cracking ice... Very good capture.', '2005-10-23 20:09:49.000000', NULL, 1),
(1805528, 244680, 43115, '<td valign="top">Very creative use of focus to make an interesting perspective on a pretty, but possibly boring scene.  It would have been so easy to take a "snapshot" of this place, but you chose a creative and unique way to show it.  Good job.</td>', 'Very creative use of focus to make an interesting perspective on a pretty, but possibly boring scene.  It would have been so easy to take a "snapshot" of this place, but you chose a creative and unique way to show it.  Good job.', '2005-10-23 20:12:03.000000', NULL, 1),
(1805531, 244978, 43115, '<td valign="top">I love this scene, I love this photo.  I love the stark contrast between the sculpture, the room, and the people.  I love the triple play on wods, here I am contemplating a picture of people contemplating a sculpture of someone contemplating.<br/> <br/> I''ve got to say it again, I love the whole set up, the coloring in the people''s clothes vs. the greys of the surroundings.  This is a personal fave of this contest.   Exceptionally well done.</td>', 'I love this scene, I love this photo.  I love the stark contrast between the sculpture, the room, and the people.  I love the triple play on wods, here I am contemplating a picture of people contemplating a sculpture of someone contemplating.  I''ve got to say it again, I love the whole set up, the coloring in the people''s clothes vs. the greys of the surroundings.  This is a personal fave of this contest.   Exceptionally well done.', '2005-10-23 20:14:51.000000', NULL, 1),
(1805536, 243304, 43115, '<td valign="top">My prediction for a ribbon.  Nicely done, though a little too strongly violet for my taste.</td>', 'My prediction for a ribbon.  Nicely done, though a little too strongly violet for my taste.', '2005-10-23 20:16:08.000000', NULL, 1),
(1805545, 244525, 43020, '<td valign="top">Hi, for me, this photo is just too dark - it''s 95% black and nothing really going on.  It''s a nice attempt and I think you should keep trying.</td>', 'Hi, for me, this photo is just too dark - it''s 95% black and nothing really going on.  It''s a nice attempt and I think you should keep trying.', '2005-10-23 20:20:59.000000', NULL, 1),
(1805547, 245146, 43020, '<td valign="top">Seems to me like an opportunity shot - the PC was there, so was your camera.  Sorry - IMHO it is not very inspiring.</td>', 'Seems to me like an opportunity shot - the PC was there, so was your camera.  Sorry - IMHO it is not very inspiring.', '2005-10-23 20:21:48.000000', NULL, 1),
(1805550, 242741, 43020, '<td valign="top">This doesn''t scream wide to me.  Nice perspective though!</td>', 'This doesn''t scream wide to me.  Nice perspective though!', '2005-10-23 20:22:23.000000', NULL, 1),
(1805554, 244514, 43020, '<td valign="top">This seems to lack anything I really want to look at.  IMHO it may need a person under that light or something?  Interesting lighting though.</td>', 'This seems to lack anything I really want to look at.  IMHO it may need a person under that light or something?  Interesting lighting though.', '2005-10-23 20:23:07.000000', NULL, 1),
(1805580, 244174, 17851, '<td valign="top">awesome photo! I love the yellow tones and mood :)....  best of luck (top ten for sure)</td>', 'awesome photo! I love the yellow tones and mood :)....  best of luck (top ten for sure)', '2005-10-23 20:44:41.000000', NULL, 1),
(1805581, 243979, 30392, '<td valign="top">Got to be a ribbon</td>', 'Got to be a ribbon', '2005-10-23 20:44:44.000000', NULL, 1),
(1805586, 244422, 17851, '<td valign="top">very nice wide angle!... should be top 10... good luck!</td>', 'very nice wide angle!... should be top 10... good luck!', '2005-10-23 20:47:30.000000', NULL, 1),
(1805588, 243477, 17851, '<td valign="top">Beautiful place, nice use of wide angle ;) ... good luck ;)</td>', 'Beautiful place, nice use of wide angle ;) ... good luck ;)', '2005-10-23 20:49:21.000000', NULL, 1),
(1805592, 244917, 17851, '<td valign="top">very cool, lots of action here! good luck ;)</td>', 'very cool, lots of action here! good luck ;)', '2005-10-23 20:50:27.000000', NULL, 1),
